'use client';

import React, { useEffect, useState } from 'react';
import { fetchLiveFixtures } from '@/shared/api/sportmonks';
import MatchCard from '@/shared/ui/MatchCard/MatchCard';
import './FixturesList.css';

interface LiveFixture {
  id: number;
  starting_at: {
    date_time: string;
  };
  participants: {
    data: {
      id: number;
      name: string;
    }[];
  };
  league: {
    data: {
      name: string;
    };
  };
  scores: {
    data: {
      score: {
        participant: string;
        goals: number;
      }[];
    }
  };
  minute?: number;
}

const LiveFixtures: React.FC = () => {
  const [fixtures, setFixtures] = useState<LiveFixture[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      setError(null);

      try {
        // В API SportMonks live-матчи возвращаются с реальной датой (могут быть с 2025 годом)
        const response = await fetchLiveFixtures();
        setFixtures(response.data || []);
      } catch (err) {
        console.error('Ошибка при загрузке live матчей:', err);
        setError(err instanceof Error ? err.message : 'Неизвестная ошибка');
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();

    // Обновляем данные каждую минуту
    const interval = setInterval(fetchData, 60000);
    return () => clearInterval(interval);
  }, []);

  // Конвертация данных API в формат наших компонентов
  const mapFixturesToMatches = (fixtures: LiveFixture[]) => {
    return fixtures.map(fixture => {
      // Получаем команды
      const homeTeam = fixture.participants.data?.[0]?.name || 'Неизвестно';
      const awayTeam = fixture.participants.data?.[1]?.name || 'Неизвестно';

      // Получаем счет
      const homeScore = fixture.scores?.data?.score?.find(s => s.participant === 'home')?.goals;
      const awayScore = fixture.scores?.data?.score?.find(s => s.participant === 'away')?.goals;

      // Форматируем время из API (уже в московской временной зоне)
      const dateObj = new Date(fixture.starting_at.date_time);
      const formattedDate = dateObj.toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' });

      // Время или минута матча
      const time = fixture.minute ? `${fixture.minute}'` : dateObj.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });

      return {
        id: fixture.id.toString(),
        home: homeTeam,
        away: awayTeam,
        status: 'LIVE' as const,
        time,
        date: formattedDate,
        tournament: fixture.league.data?.name,
        score: {
          home: homeScore !== undefined ? homeScore : 0,
          away: awayScore !== undefined ? awayScore : 0
        }
      };
    });
  };

  const matchesData = mapFixturesToMatches(fixtures);

  if (isLoading) {
    return <div className="fixtures-loading">Загрузка live матчей...</div>;
  }

  if (error) {
    return <div className="fixtures-error">❌ Ошибка: {error}</div>;
  }

  if (fixtures.length === 0) {
    return <div className="fixtures-empty">Сейчас нет матчей в прямом эфире</div>;
  }

  return (
    <div className="fixtures-list">
      <h2 className="fixtures-title">
        <span className="live-dot"></span> Матчи в прямом эфире
      </h2>
      <div className="fixtures-grid">
        {matchesData.map(match => (
          <MatchCard
            key={match.id}
            homeTeam={match.home}
            awayTeam={match.away}
            status="LIVE"
            time={match.time}
            date={match.date}
            tournament={match.tournament}
            homeScore={match.score.home}
            awayScore={match.score.away}
          />
        ))}
      </div>
    </div>
  );
};

export default LiveFixtures;
